static int32_t class_is_subclass(const SimpClassMeta *actual,
                                 const SimpClassMeta *expected) {
    if (actual == NULL || expected == NULL) abort();
    if (actual->name_length == expected->name_length &&
        memcmp(actual->name, expected->name, (size_t)actual->name_length) == 0) {
        return 1;
    }
    for (uint64_t index = 0; index < actual->base_class_count; ++index) {
        const SimpClassName *base = &actual->base_classes[index];
        if (base->name_length == expected->name_length &&
            memcmp(base->name, expected->name, (size_t)base->name_length) == 0) {
            return 1;
        }
    }
    return 0;
}

int32_t simp_object_is_instance(void *object, const SimpClassMeta *expected) {
    if (expected == NULL) abort();
    if (object == NULL) return 0;
    const SimpClassMeta *actual = NULL;
    memcpy(&actual, object, sizeof(actual));
    return class_is_subclass(actual, expected);
}

int32_t simp_value_is_type(uint64_t actual_tag, void *pointer,
                           uint64_t expected_tag, const SimpClassMeta *expected_class) {
    if (expected_tag == SIMP_ARRAY_OBJECT) {
        if (expected_class == NULL || actual_tag != SIMP_ARRAY_OBJECT || pointer == NULL) {
            return 0;
        }
        return simp_object_is_instance(pointer, expected_class);
    }
    if (expected_class != NULL) abort();
    if (actual_tag != expected_tag) return 0;
    if ((actual_tag == SIMP_ARRAY_STRING || actual_tag == SIMP_ARRAY_OBJECT ||
         actual_tag == SIMP_ARRAY_MAP || actual_tag == SIMP_ARRAY_ARRAY ||
         actual_tag == SIMP_ARRAY_BUFFER || actual_tag == SIMP_ARRAY_HANDLE) &&
        pointer == NULL) {
        return 0;
    }
    return 1;
}

int32_t simp_type_names_equal(const char *left, uint64_t left_length,
                              const char *right, uint64_t right_length) {
    if (left_length != right_length) return 0;
    if (left_length == 0) return 1;
    if (left == NULL || right == NULL || left_length > (uint64_t)SIZE_MAX) abort();
    return memcmp(left, right, (size_t)left_length) == 0;
}

const char *simp_object_type_name(void *object, uint64_t *length) {
    if (length == NULL) abort();
    if (object == NULL) {
        *length = 4;
        return "null";
    }
    const SimpClassMeta *actual = NULL;
    memcpy(&actual, object, sizeof(actual));
    if (actual == NULL) abort();
    *length = actual->name_length;
    return actual->name;
}

const char *simp_value_type_name(uint64_t tag, void *pointer, uint64_t *length) {
    if (length == NULL) abort();
    if ((tag == SIMP_ARRAY_STRING || tag == SIMP_ARRAY_OBJECT ||
         tag == SIMP_ARRAY_MAP || tag == SIMP_ARRAY_ARRAY ||
         tag == SIMP_ARRAY_BUFFER || tag == SIMP_ARRAY_HANDLE) &&
        pointer == NULL) {
        *length = 4;
        return "null";
    }
    switch (tag) {
    case SIMP_ARRAY_INTEGER: *length = 3; return "int";
    case SIMP_ARRAY_STRING: *length = 6; return "string";
    case SIMP_ARRAY_OBJECT: return simp_object_type_name(pointer, length);
    case SIMP_ARRAY_MAP: *length = 3; return "map";
    case SIMP_ARRAY_ARRAY: *length = 5; return "array";
    case SIMP_ARRAY_BOOLEAN: *length = 4; return "bool";
    case SIMP_ARRAY_FLOAT: *length = 5; return "float";
    case SIMP_ARRAY_UNSIGNED: *length = 8; return "unsigned";
    case SIMP_ARRAY_BUFFER: *length = 6; return "buffer";
    case SIMP_ARRAY_HANDLE: *length = 6; return "handle";
    case SIMP_ARRAY_TYPE: *length = 4; return "type";
    default: abort();
    }
}

int32_t simp_exception_matches(void *storage, const SimpClassMeta *expected) {
    SimpExceptionFrame *frame = (SimpExceptionFrame *)storage;
    if (frame == NULL || !frame->has_exception || frame->exception_object == NULL ||
        expected == NULL) abort();
    return simp_object_is_instance(frame->exception_object, expected);
}

static void *make_runtime_exception(const char *message, uint64_t length) {
    if ((message == NULL && length != 0) || length > (uint64_t)SIZE_MAX) abort();
    void *object = simp_gc_alloc(&simp_exception_class_meta);
    SimpRuntimeException *exception = (SimpRuntimeException *)object;
    exception->owner = object;
    char *copy = length == 0 ? NULL : (char *)malloc((size_t)length);
    if (length != 0 && copy == NULL) abort();
    if (length != 0) memcpy(copy, message, (size_t)length);
    exception->message.data = copy;
    exception->message.length = length;
    exception->runtime_owns_message = 1;
    return object;
}

void simp_exception_raise(const char *message, uint64_t length, const char *file,
                          uint64_t file_length, uint64_t line, uint64_t column) {
    if (collecting || running_destructor) {
        raise_exception(message, length, file, file_length, line, column,
                        NULL, NULL, NULL, NULL, NULL);
    }
    void *object = make_runtime_exception(message, length);
    raise_exception(message, length, file, file_length, line, column,
                    object, object, NULL, NULL, NULL);
}

void simp_exception_raise_object(void *object, void *exception_base,
                                 const char *message, uint64_t length,
                                 const char *file, uint64_t file_length,
                                 uint64_t line, uint64_t column) {
    if (object == NULL || exception_base == NULL) abort();
    raise_exception(message, length, file, file_length, line, column,
                    object, exception_base, NULL, NULL, NULL);
}

void simp_exception_rethrow(void *storage) {
    SimpExceptionFrame *frame = (SimpExceptionFrame *)storage;
    if (frame == NULL || !frame->has_exception) abort();
    char *message = frame->message;
    const uint64_t length = (uint64_t)frame->message_length;
    char *file = frame->file;
    const uint64_t file_length = (uint64_t)frame->file_length;
    const uint64_t line = frame->line;
    const uint64_t column = frame->column;
    void *exception_object = frame->exception_object;
    void *exception_base = frame->exception_base;
    SimpTraceSnapshot *trace = frame->trace;
    if (exception_object == NULL || exception_base == NULL) abort();
    frame->message = NULL;
    frame->message_length = 0;
    frame->file = NULL;
    frame->file_length = 0;
    frame->line = 0;
    frame->column = 0;
    frame->exception_object = NULL;
    frame->exception_base = NULL;
    frame->has_exception = 0;
    frame->trace = NULL;
    raise_exception(message, length, file, file_length, line, column,
                    exception_object, exception_base, message, file, trace);
}

static int valid_reference_offset(const SimpClassMeta *metadata, uint64_t offset) {
    return metadata->object_size >= sizeof(void *) &&
           offset >= sizeof(void *) &&
           offset <= metadata->object_size - sizeof(void *) &&
           offset % alignof(void *) == 0;
}

static HeapNode *find_object(const void *object) {
    for (HeapNode *node = heap; node != NULL; node = node->next) {
        if (node->object == object) {
            return node;
        }
    }
    return NULL;
}

static HeapNode *find_containing_object(const void *object) {
    const uintptr_t address = (uintptr_t)object;
    for (HeapNode *node = heap; node != NULL; node = node->next) {
        const uintptr_t start = (uintptr_t)node->object;
        if (address < start) continue;
        if (address - start < node->allocation_size) return node;
    }
    return NULL;
}

static void mark_object(void *object, HeapNode **worklist, size_t *work_count) {
    if (object == NULL) {
        return;
    }
    HeapNode *node = find_containing_object(object);
    if (node == NULL || node->marked) {
        return;
    }
    node->marked = 1;
    worklist[(*work_count)++] = node;
}

static int gc_push(SimpRootFrame *frame, void *const *slots,
                   const uint64_t *const *tags, uint64_t count) {
    if (frame == NULL || (count != 0 && slots == NULL)) {
        return 0;
    }
    for (SimpRootFrame *active = root_frame; active != NULL; active = active->previous) {
        if (active == frame) {
            return 0;
        }
    }
    for (uint64_t index = 0; index < count; ++index) {
        if (slots[index] == NULL) {
            return 0;
        }
    }
    frame->previous = root_frame;
    frame->count = count;
    frame->slots = slots;
    frame->tags = tags;
    root_frame = frame;
    return 1;
}

int simp_gc_push(SimpRootFrame *frame, void *const *slots, uint64_t count) {
    return gc_push(frame, slots, NULL, count);
}

int simp_gc_pop(SimpRootFrame *frame) {
    if (frame == NULL || root_frame != frame) {
        return 0;
    }
    root_frame = frame->previous;
    frame->previous = NULL;
    frame->count = 0;
    frame->slots = NULL;
    frame->tags = NULL;
    return 1;
}

void simp_gc_push_or_abort(SimpRootFrame *frame, void *const *slots, uint64_t count) {
    if (!simp_gc_push(frame, slots, count)) {
        abort();
    }
}

void simp_gc_push_tagged_or_abort(SimpRootFrame *frame, void *const *slots,
                                  const uint64_t *const *tags, uint64_t count) {
    if (!gc_push(frame, slots, tags, count)) abort();
}

void simp_gc_pop_or_abort(SimpRootFrame *frame) {
    if (!simp_gc_pop(frame)) {
        abort();
    }
}

void simp_gc_require_alive(void *object, const char *file, uint64_t file_length,
                           uint64_t line, uint64_t column) {
    if (object == NULL) {
        return;
    }
    HeapNode *node = find_containing_object(object);
    if (node == NULL)
        simp_exception_raise("invalid object reference", 24, file, file_length, line, column);
    if (node->destroyed && !node->destroying)
        simp_exception_raise("object has been destroyed", 25, file, file_length, line, column);
}

void simp_value_require_tag(uint64_t actual, uint64_t expected, const char *file,
                            uint64_t file_length, uint64_t line, uint64_t column) {
    if (actual != expected) {
        static const char message[] = "'any' value does not hold the requested type";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
}

void simp_value_require_class(uint64_t actual_tag, void *pointer,
                              const SimpClassMeta *expected, const char *file,
                              uint64_t file_length, uint64_t line, uint64_t column) {
    if (actual_tag != SIMP_ARRAY_OBJECT) {
        static const char message[] = "'any' value does not hold an object reference";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    if (pointer == NULL) {
        /* A null object reference is compatible with every class type. */
        return;
    }
    const SimpClassMeta *actual;
    memcpy(&actual, pointer, sizeof(actual));
    if (actual != expected) {
        static const char message[] =
            "'any' value holds a different class than the requested type";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
}

void simp_value_require_map(uint64_t actual_tag, void *pointer, const char *file,
                           uint64_t file_length, uint64_t line, uint64_t column) {
    static const char message[] = "'any' value does not hold a map reference";
    if (actual_tag != SIMP_ARRAY_MAP) {
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    if (pointer == NULL) {
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    HeapNode *node = find_object(pointer);
    if (node == NULL || !node->is_map) {
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
}

void simp_value_require_array(uint64_t actual_tag, void *pointer, const char *file,
                              uint64_t file_length, uint64_t line, uint64_t column) {
    static const char message[] = "'any' value does not hold an array reference";
    if (actual_tag != SIMP_ARRAY_ARRAY) {
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    if (pointer == NULL) {
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    HeapNode *node = find_object(pointer);
    if (node == NULL || !node->is_array) {
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
}

static int dynamic_value_is_gc_reference(uint64_t tag) {
    return tag == SIMP_ARRAY_OBJECT || tag == SIMP_ARRAY_MAP ||
           tag == SIMP_ARRAY_ARRAY || tag == SIMP_ARRAY_BUFFER;
}

void simp_value_require_buffer(uint64_t actual_tag, void *pointer, const char *file,
                               uint64_t file_length, uint64_t line, uint64_t column) {
    static const char message[] = "'any' value does not hold a buffer reference";
    if (actual_tag == SIMP_ARRAY_OBJECT && pointer == NULL) return;
    if (actual_tag != SIMP_ARRAY_BUFFER || pointer == NULL) {
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    HeapNode *node = find_object(pointer);
    if (node == NULL || !node->is_buffer) {
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
}

void simp_value_require_handle(uint64_t actual_tag, void *pointer, const char *file,
                               uint64_t file_length, uint64_t line, uint64_t column) {
    static const char message[] = "'any' value does not hold a handle";
    if ((actual_tag == SIMP_ARRAY_HANDLE) ||
        (actual_tag == SIMP_ARRAY_OBJECT && pointer == NULL)) {
        return;
    }
    simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
}


void *simp_gc_root(void *object) {
    HeapNode *node = find_containing_object(object);
    if (node == NULL) abort();
    return node->object;
}

void simp_gc_begin_destroy(void *object, const char *file, uint64_t file_length,
                           uint64_t line, uint64_t column) {
    HeapNode *node = find_containing_object(object);
    if (node == NULL)
        simp_exception_raise("invalid object reference", 24, file, file_length, line, column);
    if (node->destroyed)
        simp_exception_raise("object has already been destroyed", 32,
                             file, file_length, line, column);
    node->destroyed = 1;
    node->destroying = 1;
    node->destroy_previous = destroy_stack;
    destroy_stack = node;
}

void simp_gc_end_destroy(void *object) {
    HeapNode *node = find_containing_object(object);
    if (node == NULL || !node->destroying || destroy_stack != node) {
        abort();
    }
    node->destroying = 0;
    destroy_stack = node->destroy_previous;
    node->destroy_previous = NULL;
}

static HeapNode **allocate_worklist(void) {
    if (object_count > SIZE_MAX / sizeof(HeapNode *)) {
        abort();
    }
    HeapNode **worklist = object_count == 0 ? NULL :
        (HeapNode **)malloc(object_count * sizeof(*worklist));
    if (object_count != 0 && worklist == NULL) abort();
    return worklist;
}

static void mark_roots(HeapNode **worklist, size_t *work_count) {
    /* Scan every registered Simple thread's root-frame chain, not just the
     * collecting thread's. This is race-free because only one Simple
     * thread ever runs managed code at a time (see the "Threads" note in
     * SIMPLE-LANGUAGE-NOTES.md): every other registered thread is, right
     * now, blocked waiting to (re)acquire the global lock, so its
     * root-frame chain cannot be concurrently mutated while we walk it. */
    for (SimpThreadRegistration *thread = thread_registry; thread != NULL;
         thread = thread->next) {
        for (SimpRootFrame *frame = *thread->root_frame_slot; frame != NULL;
             frame = frame->previous) {
            for (uint64_t index = 0; index < frame->count; ++index) {
                if (frame->slots == NULL || frame->slots[index] == NULL) abort();
                void *object = NULL;
                memcpy(&object, frame->slots[index], sizeof(object));
                if (frame->tags != NULL && frame->tags[index] != NULL) {
                    uint64_t tag = 0;
                    memcpy(&tag, frame->tags[index], sizeof(tag));
                    if (!dynamic_value_is_gc_reference(tag)) continue;
                }
                mark_object(object, worklist, work_count);
            }
        }
    }
}

static void trace_graph(HeapNode **worklist, size_t *work_count) {
    while (*work_count != 0) {
        HeapNode *node = worklist[--(*work_count)];
        if (node->is_array) {
            const SimpArray *array = (const SimpArray *)node->object;
            for (uint64_t index = 0; index < array->length; ++index) {
                const SimpArrayValue *value = &array->values[index];
                if (dynamic_value_is_gc_reference(value->tag)) {
                    mark_object(value->pointer, worklist, work_count);
                }
            }
            continue;
        }
        if (node->is_map) {
            const SimpMap *map = (const SimpMap *)node->object;
            for (uint64_t index = 0; index < map->length; ++index) {
                const SimpArrayValue *value = &map->entries[index].value;
                if (dynamic_value_is_gc_reference(value->tag)) {
                    mark_object(value->pointer, worklist, work_count);
                }
            }
            continue;
        }
        const SimpClassMeta *metadata = NULL;
        memcpy(&metadata, node->object, sizeof(metadata));
        if (metadata == NULL) abort();
        for (uint64_t index = 0; index < metadata->reference_field_count; ++index) {
            const uint64_t offset = metadata->reference_field_offsets[index];
            if (!valid_reference_offset(metadata, offset)) abort();
            void *child = NULL;
            memcpy(&child, (const unsigned char *)node->object + offset, sizeof(child));
            mark_object(child, worklist, work_count);
        }
        for (uint64_t index = 0; index < metadata->dynamic_reference_field_count; ++index) {
            const uint64_t offset = metadata->dynamic_reference_field_offsets[index];
            if (!valid_reference_offset(metadata, offset) ||
                offset < offsetof(SimpArrayValue, pointer)) abort();
            uint64_t tag = 0;
            memcpy(&tag, (const unsigned char *)node->object +
                             offset - offsetof(SimpArrayValue, pointer),
                   sizeof(tag));
            if (!dynamic_value_is_gc_reference(tag)) continue;
            void *child = NULL;
            memcpy(&child, (const unsigned char *)node->object + offset, sizeof(child));
            mark_object(child, worklist, work_count);
        }
    }
}

void simp_gc_collect(void) {
    if (collecting || running_destructor) abort();
    collecting = 1;
    for (HeapNode *node = heap; node != NULL; node = node->next) {
        node->marked = 0;
    }
    HeapNode **worklist = allocate_worklist();
    size_t work_count = 0;
    mark_roots(worklist, &work_count);
    trace_graph(worklist, &work_count);

    for (HeapNode *node = heap; node != NULL; node = node->next) {
        if (node->marked || node->destroyed) continue;
        const SimpClassMeta *metadata = NULL;
        memcpy(&metadata, node->object, sizeof(metadata));
        if (metadata == NULL) abort();
        node->destroyed = 1;
        if (metadata->finalize != NULL) {
            node->destroying = 1;
            running_destructor = 1;
            metadata->finalize(node->object);
            running_destructor = 0;
            node->destroying = 0;
        }
    }

    /* Finalizers may attach dead objects to live objects; retain, but keep them destroyed. */
    for (HeapNode *node = heap; node != NULL; node = node->next) node->marked = 0;
    work_count = 0;
    mark_roots(worklist, &work_count);
    trace_graph(worklist, &work_count);
    free(worklist);

    HeapNode **link = &heap;
    while (*link != NULL) {
        HeapNode *node = *link;
        if (!node->marked) {
            *link = node->next;
            if (node->is_array) {
                free(((SimpArray *)node->object)->values);
            }
            if (node->is_map) {
                SimpMap *map = (SimpMap *)node->object;
                for (uint64_t index = 0; index < map->length; ++index) {
                    free((void *)map->entries[index].key);
                }
                free(map->entries);
                free(map->buckets);
            }
            if (node->is_buffer) free(((SimpBuffer *)node->object)->data);
            free(node->object);
            free(node);
            --object_count;
        } else {
            link = &node->next;
        }
    }
    collecting = 0;
}

void *simp_gc_alloc(const SimpClassMeta *metadata) {
    if (collecting || running_destructor) abort();
    if (metadata == NULL || metadata->object_size < sizeof(void *) ||
        metadata->object_size > (uint64_t)SIZE_MAX ||
        (metadata->reference_field_count != 0 &&
         metadata->reference_field_offsets == NULL) ||
        (metadata->dynamic_reference_field_count != 0 &&
         metadata->dynamic_reference_field_offsets == NULL)) {
        abort();
    }
    for (uint64_t index = 0; index < metadata->reference_field_count; ++index) {
        const uint64_t offset = metadata->reference_field_offsets[index];
        if (!valid_reference_offset(metadata, offset)) {
            abort();
        }
    }
    for (uint64_t index = 0; index < metadata->dynamic_reference_field_count; ++index) {
        const uint64_t offset = metadata->dynamic_reference_field_offsets[index];
        if (!valid_reference_offset(metadata, offset) ||
            offset < offsetof(SimpArrayValue, pointer)) {
            abort();
        }
    }
    simp_gc_collect();
    void *object = calloc(1, (size_t)metadata->object_size);
    HeapNode *node = (HeapNode *)malloc(sizeof(*node));
    if (object == NULL || node == NULL) {
        free(object);
        free(node);
        abort();
    }
    memcpy(object, &metadata, sizeof(metadata));
    node->object = object;
    node->allocation_size = (size_t)metadata->object_size;
    node->is_array = 0;
    node->is_map = 0;
    node->is_buffer = metadata == &buffer_metadata;
    node->marked = 0;
    node->destroyed = 0;
    node->destroying = 0;
    node->destroy_previous = NULL;
    node->constructing = 0;
    node->construct_previous = NULL;
    node->next = heap;
    heap = node;
    ++object_count;
    return object;
}

void *simp_gc_alloc_array(uint64_t length) {
    if (collecting || running_destructor || length > INT32_MAX ||
        length > SIZE_MAX / sizeof(SimpArrayValue)) {
        abort();
    }
    simp_gc_collect();
    SimpArray *array = (SimpArray *)calloc(1, sizeof(*array));
    HeapNode *node = (HeapNode *)malloc(sizeof(*node));
    SimpArrayValue *values = length == 0 ? NULL :
        (SimpArrayValue *)calloc((size_t)length, sizeof(*values));
    if (array == NULL || node == NULL || (length != 0 && values == NULL)) {
        free(array);
        free(node);
        free(values);
        abort();
    }
    array->metadata = &array_metadata;
    array->length = length;
    array->capacity = length;
    array->values = values;
    for (uint64_t index = 0; index < length; ++index) values[index].tag = SIMP_ARRAY_OBJECT;
    node->object = array;
    node->allocation_size = sizeof(*array);
    node->is_array = 1;
    node->is_map = 0;
    node->is_buffer = 0;
    node->marked = 0;
    node->destroyed = 0;
    node->destroying = 0;
    node->destroy_previous = NULL;
    node->constructing = 0;
    node->construct_previous = NULL;
    node->next = heap;
    heap = node;
    ++object_count;
    return array;
}

void *simp_gc_alloc_map(void) {
    if (collecting || running_destructor) abort();
    simp_gc_collect();
    SimpMap *map = (SimpMap *)calloc(1, sizeof(*map));
    HeapNode *node = (HeapNode *)malloc(sizeof(*node));
    if (map == NULL || node == NULL) {
        free(map);
        free(node);
        abort();
    }
    map->metadata = &map_metadata;
    node->object = map;
    node->allocation_size = sizeof(*map);
    node->is_array = 0;
    node->is_map = 1;
    node->is_buffer = 0;
    node->marked = 0;
    node->destroyed = 0;
    node->destroying = 0;
    node->destroy_previous = NULL;
    node->constructing = 0;
    node->construct_previous = NULL;
    node->next = heap;
    heap = node;
    ++object_count;
    return map;
}

static SimpArray *checked_array(void *object, const char *file, uint64_t file_length,
                                uint64_t line, uint64_t column) {
    if (object == NULL) {
        static const char message[] = "null array reference";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    HeapNode *node = find_object(object);
    if (node == NULL || !node->is_array) {
        static const char message[] = "invalid array reference";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    return (SimpArray *)object;
}

void simp_array_resize(void *object, int32_t length, const char *file,
                       uint64_t file_length, uint64_t line, uint64_t column) {
    SimpArray *array = checked_array(object, file, file_length, line, column);
    if (length < 0) {
        static const char message[] = "array length must not be negative";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    const uint64_t new_length = (uint64_t)length;
    if (new_length > SIZE_MAX / sizeof(SimpArrayValue)) {
        static const char message[] = "array length exceeds allocation limit";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    if (new_length > array->capacity) {
        uint64_t capacity = array->capacity == 0 ? 1 : array->capacity;
        while (capacity < new_length) {
            if (capacity > (uint64_t)INT32_MAX / 2) {
                capacity = new_length;
                break;
            }
            capacity *= 2;
        }
        if (capacity > SIZE_MAX / sizeof(SimpArrayValue)) capacity = new_length;
        SimpArrayValue *values = (SimpArrayValue *)realloc(
            array->values, (size_t)capacity * sizeof(*values));
        if (values == NULL) abort();
        array->values = values;
        array->capacity = capacity;
    }
    if (new_length < array->length) {
        memset(array->values + new_length, 0,
               (size_t)(array->length - new_length) * sizeof(*array->values));
    } else {
        for (uint64_t index = array->length; index < new_length; ++index) {
            array->values[index] = (SimpArrayValue){SIMP_ARRAY_OBJECT, 0, NULL, 0};
        }
    }
    array->length = new_length;
}

void simp_array_append(void *object, const SimpArrayValue *value, const char *file,
                       uint64_t file_length, uint64_t line, uint64_t column) {
    SimpArray *array = checked_array(object, file, file_length, line, column);
    if (array->length == INT32_MAX) {
        static const char message[] = "array length exceeds int range";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    if (value == NULL) abort();
    const SimpArrayValue copy = *value;
    simp_array_resize(array, (int32_t)(array->length + 1), file, file_length, line, column);
    array->values[array->length - 1] = copy;
}

static SimpMap *checked_map(void *object, const char *file, uint64_t file_length,
                            uint64_t line, uint64_t column) {
    if (object == NULL) {
        static const char message[] = "null map reference";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    HeapNode *node = find_object(object);
    if (node == NULL || !node->is_map) {
        static const char message[] = "invalid map reference";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    return (SimpMap *)object;
}

static SimpBuffer *checked_buffer(void *object, const char *file, uint64_t file_length,
                                  uint64_t line, uint64_t column) {
    if (object == NULL) {
        static const char message[] = "null buffer reference";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    HeapNode *node = find_object(object);
    if (node == NULL || !node->is_buffer) {
        static const char message[] = "invalid buffer reference";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    return (SimpBuffer *)object;
}

static void buffer_reserve(SimpBuffer *buffer, uint64_t capacity) {
    if (capacity > (uint64_t)SIZE_MAX) abort();
    if (capacity <= buffer->capacity) return;
    uint64_t grown = buffer->capacity == 0 ? 8 : buffer->capacity;
    while (grown < capacity) {
        if (grown > (uint64_t)INT32_MAX / 2) {
            grown = capacity;
            break;
        }
        grown *= 2;
    }
    uint8_t *data = (uint8_t *)realloc(buffer->data, (size_t)grown);
    if (data == NULL) abort();
    buffer->data = data;
    buffer->capacity = grown;
}

void *simp_buffer_new(int32_t length, const char *file, uint64_t file_length,
                      uint64_t line, uint64_t column) {
    if (length < 0) {
        static const char message[] = "buffer length cannot be negative";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    SimpBuffer *buffer = (SimpBuffer *)simp_gc_alloc(&buffer_metadata);
    if (length > 0) {
        buffer->data = (uint8_t *)calloc((size_t)length, sizeof(*buffer->data));
        if (buffer->data == NULL) abort();
        buffer->length = (uint64_t)length;
        buffer->capacity = (uint64_t)length;
    }
    return buffer;
}

void *simp_buffer_copy(void *object, const char *file, uint64_t file_length,
                       uint64_t line, uint64_t column) {
    if (object == NULL) return NULL;
    SimpBuffer *source = checked_buffer(object, file, file_length, line, column);
    SimpBuffer *copy = (SimpBuffer *)simp_gc_alloc(&buffer_metadata);
    if (source->length != 0) {
        copy->data = (uint8_t *)malloc((size_t)source->length);
        if (copy->data == NULL) abort();
        memcpy(copy->data, source->data, (size_t)source->length);
        copy->length = source->length;
        copy->capacity = source->length;
    }
    return copy;
}

static int64_t normalize_collection_index(int32_t index, uint64_t length) {
    int64_t normalized = index;
    if (normalized < 0) normalized += (int64_t)length;
    return normalized;
}

static int64_t normalize_slice_bound(int32_t bound, uint64_t length, int32_t step,
                                    int is_start, int has_bound) {
    int64_t normalized;
    if (!has_bound) {
        if (is_start) return step > 0 ? 0 : (int64_t)length - 1;
        return step > 0 ? (int64_t)length : -1;
    }
    normalized = bound;
    if (normalized < 0) normalized += (int64_t)length;
    if (step > 0) {
        if (normalized < 0) return 0;
        if ((uint64_t)normalized > length) return (int64_t)length;
    } else {
        if (normalized < -1) return -1;
        if (normalized >= (int64_t)length) return (int64_t)length - 1;
    }
    return normalized;
}

void *simp_buffer_slice_ex(void *object, int32_t start, int32_t end,
                           int has_start, int has_end, const char *file,
                           uint64_t file_length, uint64_t line, uint64_t column) {
    SimpBuffer *source = checked_buffer(object, file, file_length, line, column);
    const int64_t first = normalize_slice_bound(start, source->length, 1, 1, has_start);
    const int64_t last = normalize_slice_bound(end, source->length, 1, 0, has_end);
    const uint64_t length = last > first ? (uint64_t)(last - first) : 0;
    SimpBuffer *copy = (SimpBuffer *)simp_gc_alloc(&buffer_metadata);
    if (length != 0) {
        copy->data = (uint8_t *)malloc((size_t)length);
        if (copy->data == NULL) abort();
        memcpy(copy->data, source->data + first, (size_t)length);
        copy->length = length;
        copy->capacity = length;
    }
    return copy;
}

void *simp_buffer_slice(void *object, int32_t start, int32_t end, const char *file,
                        uint64_t file_length, uint64_t line, uint64_t column) {
    return simp_buffer_slice_ex(object, start, end, 1, 1, file,
                                file_length, line, column);
}

void simp_buffer_resize(void *object, int32_t length, const char *file,
                        uint64_t file_length, uint64_t line, uint64_t column) {
    SimpBuffer *buffer = checked_buffer(object, file, file_length, line, column);
    if (length < 0) {
        static const char message[] = "buffer length cannot be negative";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    const uint64_t new_length = (uint64_t)length;
    if (new_length > buffer->length) {
        buffer_reserve(buffer, new_length);
        memset(buffer->data + buffer->length, 0,
               (size_t)(new_length - buffer->length));
    }
    buffer->length = new_length;
}

void simp_buffer_clear(void *object, const char *file, uint64_t file_length,
                       uint64_t line, uint64_t column) {
    simp_buffer_resize(object, 0, file, file_length, line, column);
}

void simp_buffer_append(void *object, uint64_t value, const char *file,
                        uint64_t file_length, uint64_t line, uint64_t column) {
    SimpBuffer *buffer = checked_buffer(object, file, file_length, line, column);
    if (buffer->length >= (uint64_t)INT32_MAX) {
        static const char message[] = "buffer length out of bounds";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    buffer_reserve(buffer, buffer->length + 1);
    buffer->data[buffer->length++] = (uint8_t)value;
}

uint64_t simp_buffer_get(void *object, int32_t index, const char *file,
                         uint64_t file_length, uint64_t line, uint64_t column) {
    SimpBuffer *buffer = checked_buffer(object, file, file_length, line, column);
    const int64_t normalized = normalize_collection_index(index, buffer->length);
    if (normalized < 0 || (uint64_t)normalized >= buffer->length) {
        static const char message[] = "buffer index out of bounds";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    return buffer->data[normalized];
}

void simp_buffer_set(void *object, int32_t index, uint64_t value, const char *file,
                     uint64_t file_length, uint64_t line, uint64_t column) {
    SimpBuffer *buffer = checked_buffer(object, file, file_length, line, column);
    const int64_t normalized = normalize_collection_index(index, buffer->length);
    if (normalized < 0 || (uint64_t)normalized >= buffer->length) {
        static const char message[] = "buffer index out of bounds";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    buffer->data[normalized] = (uint8_t)value;
}

static int map_key_matches(const SimpMapEntry *entry, const char *key,
                           uint64_t key_length) {
    return entry->key_length == key_length &&
           (key_length == 0 || memcmp(entry->key, key, (size_t)key_length) == 0);
}

static uint64_t map_key_hash(const char *key, uint64_t key_length) {
    uint64_t hash = UINT64_C(14695981039346656037);
    for (uint64_t index = 0; index < key_length; ++index) {
        hash ^= (unsigned char)key[index];
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}

static uint64_t map_find_index(const SimpMap *map, const char *key,
                               uint64_t key_length, uint64_t hash) {
    if (map->bucket_capacity == 0) return UINT64_MAX;
    const uint64_t mask = map->bucket_capacity - 1;
    uint64_t bucket = hash & mask;
    for (uint64_t probes = 0; probes < map->bucket_capacity; ++probes) {
        const uint64_t stored = map->buckets[bucket];
        if (stored == 0) return UINT64_MAX;
        const uint64_t index = stored - 1;
        const SimpMapEntry *entry = &map->entries[index];
        if (entry->hash == hash && map_key_matches(entry, key, key_length)) return index;
        bucket = (bucket + 1) & mask;
    }
    return UINT64_MAX;
}

static void map_rebuild_index(SimpMap *map, uint64_t capacity) {
    if (capacity < 8 || (capacity & (capacity - 1)) != 0 ||
        capacity > SIZE_MAX / sizeof(uint64_t)) abort();
    uint64_t *buckets = (uint64_t *)calloc((size_t)capacity, sizeof(*buckets));
    if (buckets == NULL) abort();
    const uint64_t mask = capacity - 1;
    for (uint64_t index = 0; index < map->length; ++index) {
        uint64_t bucket = map->entries[index].hash & mask;
        while (buckets[bucket] != 0) bucket = (bucket + 1) & mask;
        buckets[bucket] = index + 1;
    }
    free(map->buckets);
    map->buckets = buckets;
    map->bucket_capacity = capacity;
}

void *simp_map_get(void *object, const char *key, uint64_t key_length, const char *file,
                   uint64_t file_length, uint64_t line, uint64_t column) {
    SimpMap *map = checked_map(object, file, file_length, line, column);
    if ((key == NULL && key_length != 0) || key_length > (uint64_t)SIZE_MAX) abort();
    const uint64_t index = map_find_index(map, key, key_length,
                                          map_key_hash(key, key_length));
    if (index != UINT64_MAX) return &map->entries[index].value;
    static const char message[] = "map key not found";
    simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    abort();
}

int32_t simp_map_contains(void *object, const char *key, uint64_t key_length,
                          const char *file, uint64_t file_length, uint64_t line,
                          uint64_t column) {
    SimpMap *map = checked_map(object, file, file_length, line, column);
    if ((key == NULL && key_length != 0) || key_length > (uint64_t)SIZE_MAX) abort();
    return map_find_index(map, key, key_length, map_key_hash(key, key_length)) !=
                   UINT64_MAX;
}

void *simp_map_entry_at(void *object, uint64_t index, const char *file,
                        uint64_t file_length, uint64_t line, uint64_t column) {
    SimpMap *map = checked_map(object, file, file_length, line, column);
    if (index >= map->length) {
        static const char message[] = "map iteration index out of bounds";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    return &map->entries[index];
}

void simp_map_set(void *object, const char *key, uint64_t key_length,
                  const SimpArrayValue *value,
                  const char *file, uint64_t file_length, uint64_t line, uint64_t column) {
    SimpMap *map = checked_map(object, file, file_length, line, column);
    if (value == NULL || (key == NULL && key_length != 0) ||
        key_length > (uint64_t)SIZE_MAX) abort();
    const uint64_t hash = map_key_hash(key, key_length);
    const uint64_t existing = map_find_index(map, key, key_length, hash);
    if (existing != UINT64_MAX) {
        map->entries[existing].value = *value;
        return;
    }
    if (map->length >= INT32_MAX) abort();
    char *key_copy = (char *)malloc(key_length == 0 ? 1 : (size_t)key_length);
    if (key_copy == NULL) abort();
    if (key_length != 0) memcpy(key_copy, key, (size_t)key_length);
    if (map->length == map->capacity) {
        const uint64_t capacity = map->capacity == 0 ? 4 : map->capacity * 2;
        if (capacity < map->capacity ||
            capacity > SIZE_MAX / sizeof(SimpMapEntry)) abort();
        SimpMapEntry *entries =
            (SimpMapEntry *)realloc(map->entries, (size_t)capacity * sizeof(*entries));
        if (entries == NULL) {
            free(key_copy);
            abort();
        }
        map->entries = entries;
        map->capacity = capacity;
    }
    if (map->bucket_capacity == 0 ||
        map->length + 1 > map->bucket_capacity / 2) {
        uint64_t bucket_capacity = map->bucket_capacity == 0 ? 8 : map->bucket_capacity;
        while (map->length + 1 > bucket_capacity / 2) {
            if (bucket_capacity > UINT64_MAX / 2) {
                free(key_copy);
                abort();
            }
            bucket_capacity *= 2;
        }
        map_rebuild_index(map, bucket_capacity);
    }
    SimpMapEntry *entry = &map->entries[map->length++];
    entry->key = key_copy;
    entry->key_length = key_length;
    entry->hash = hash;
    entry->value = *value;
    uint64_t bucket = hash & (map->bucket_capacity - 1);
    while (map->buckets[bucket] != 0) {
        bucket = (bucket + 1) & (map->bucket_capacity - 1);
    }
    map->buckets[bucket] = map->length;
}

int32_t simp_map_remove(void *object, const char *key, uint64_t key_length,
                        const char *file, uint64_t file_length, uint64_t line,
                        uint64_t column) {
    SimpMap *map = checked_map(object, file, file_length, line, column);
    if ((key == NULL && key_length != 0) || key_length > (uint64_t)SIZE_MAX) abort();
    const uint64_t index = map_find_index(map, key, key_length,
                                          map_key_hash(key, key_length));
    if (index == UINT64_MAX) return 0;
    free((void *)map->entries[index].key);
    if (index + 1 < map->length) {
        memmove(&map->entries[index], &map->entries[index + 1],
                (size_t)(map->length - index - 1) * sizeof(*map->entries));
    }
    --map->length;
    if (map->bucket_capacity != 0) {
        map_rebuild_index(map, map->bucket_capacity);
    }
    return 1;
}

void *simp_map_slice_ex(void *object, int32_t start, int32_t end,
                        int has_start, int has_end, const char *file,
                        uint64_t file_length, uint64_t line, uint64_t column) {
    SimpMap *source = checked_map(object, file, file_length, line, column);
    const int64_t first = normalize_slice_bound(start, source->length, 1, 1, has_start);
    const int64_t last = normalize_slice_bound(end, source->length, 1, 0, has_end);
    SimpMap *copy = (SimpMap *)simp_gc_alloc_map();
    for (int64_t index = first; index < last; ++index) {
        const SimpMapEntry *entry = &source->entries[index];
        simp_map_set(copy, entry->key, entry->key_length, &entry->value,
                     file, file_length, line, column);
    }
    return copy;
}

void *simp_map_slice(void *object, int32_t start, int32_t end, const char *file,
                     uint64_t file_length, uint64_t line, uint64_t column) {
    return simp_map_slice_ex(object, start, end, 1, 1, file,
                             file_length, line, column);
}

void *simp_array_index(void *object, int32_t index, const char *file,
                       uint64_t file_length, uint64_t line, uint64_t column) {
    SimpArray *array = checked_array(object, file, file_length, line, column);
    const int64_t normalized = normalize_collection_index(index, array->length);
    if (normalized < 0 || (uint64_t)normalized >= array->length) {
        static const char message[] = "array index out of bounds";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    return &array->values[normalized];
}

void *simp_array_slice_ex(void *object, int32_t start, int32_t end, int32_t step,
                          int has_start, int has_end, const char *file,
                          uint64_t file_length, uint64_t line, uint64_t column) {
    SimpArray *source = checked_array(object, file, file_length, line, column);
    if (step == 0) {
        static const char message[] = "array slice step cannot be zero";
        simp_exception_raise(message, sizeof(message) - 1, file, file_length, line, column);
    }
    const int64_t first = normalize_slice_bound(start, source->length, step, 1, has_start);
    const int64_t last = normalize_slice_bound(end, source->length, step, 0, has_end);
    uint64_t length = 0;
    for (int64_t index = first; step > 0 ? index < last : index > last; index += step) {
        ++length;
    }
    SimpArray *copy = (SimpArray *)simp_gc_alloc_array(length);
    uint64_t destination = 0;
    for (int64_t index = first; step > 0 ? index < last : index > last; index += step) {
        copy->values[destination++] = source->values[index];
    }
    return copy;
}

void *simp_array_slice(void *object, int32_t start, int32_t end, const char *file,
                       uint64_t file_length, uint64_t line, uint64_t column) {
    return simp_array_slice_ex(object, start, end, 1, 1, 1, file,
                               file_length, line, column);
}

size_t simp_gc_heap_count(void) {
    return object_count;
}
